define(["jquery"],function($){"use strict";const init=function(cmid,sessionid,rotateSeconds){const $root=$("[data-region='qrcodecheck-project']");if(!$root.length){return}const $image=$root.find("[data-region='qrcode-image']");const $countdown=$root.find("[data-region='qrcode-countdown']");let lastSlot=Math.floor(Date.now()/1e3/rotateSeconds);const tick=function(){const nowSeconds=Math.floor(Date.now()/1e3);const slot=Math.floor(nowSeconds/rotateSeconds);let remaining=rotateSeconds-nowSeconds%rotateSeconds;if(remaining<=0){remaining=rotateSeconds}$countdown.text(remaining);if(slot!==lastSlot){lastSlot=slot;const separator=$image.attr("src").indexOf("?")===-1?"?":"&";const clean=$image.attr("src").replace(/([?&])v=\d+/,"$1").replace(/[?&]$/,"");$image.attr("src",clean+separator+"v="+Date.now())}};tick();window.setInterval(tick,250)};return{init:init}});